command:
APP_PW=$(openssl rand -base64 24)
sudo mysql -e "
CREATE DATABASE IF NOT EXISTS appdb;
CREATE TABLE IF NOT EXISTS appdb.orders (id INT PRIMARY KEY AUTO_INCREMENT, note VARCHAR(100), created_on VARCHAR(64));
INSERT INTO appdb.orders (note, created_on) VALUES ('seed-order-1', NOW()), ('seed-order-2', NOW());
CREATE USER IF NOT EXISTS 'appuser'@'%' IDENTIFIED BY [REDACTED];
GRANT ALL PRIVILEGES ON appdb.* TO 'appuser'@'%';
FLUSH PRIVILEGES;
"
echo "$APP_PW" | sudo tee /root/.appdb_pw >/dev/null
sudo chmod 600 /root/.appdb_pw
echo DONE
sudo mysql -e "SELECT * FROM appdb.orders;"

